const legacySharedGear=Object.keys(itemDB).filter(function(n){return itemDB[n]&&itemDB[n].class==='all'});
const classGearLabels={warrior:'Ironbound',ranger:'Hawkeye',mage:'Spellweaver',summoner:'Soulbinder'};
function classGearName(name,cls){var slot=itemDB[name]&&itemDB[name].slot||'',suffix=slot==='ring'?' Band':slot==='amulet'?(cls==='warrior'?' Crest':cls==='ranger'?' Pendant':cls==='mage'?' Sigil':' Talisman'):slot==='cape'?' Mantle':slot==='head'?' Headguard':slot==='gloves'?' Handwraps':slot==='body'?' Vestment':' Gear';return name+' · '+classGearLabels[cls]+suffix}
function specialiseLegacyGear(base,cls){var copy=Object.assign({},base,{class:cls});var d=Number(base.damage)||0,r=Number(base.range)||0,v=Number(base.defence)||0;if(cls==='warrior'){copy.damage=Math.max(d,Math.round(d*1.15));copy.range=Math.round(r*.25);copy.defence=Math.max(v,Math.round(v*1.3))}else if(cls==='ranger'){copy.damage=Math.max(d,Math.round(d*1.05));copy.range=Math.max(r,Math.round(r*1.4));copy.defence=Math.round(v*.7)}else if(cls==='mage'){copy.damage=Math.max(d,Math.round(d*1.25));copy.range=Math.max(r,Math.round(r*1.25));copy.defence=Math.round(v*.55)}else{copy.damage=Math.max(d,Math.round(d*1.15));copy.range=Math.max(r,Math.round(r*1.2));copy.defence=Math.round(v*.8);copy.summonPower=Math.max(1,Math.round((d+r*.5+v*.25)*.35))}if(copy.req&&copy.req.Defence&&cls!=='warrior'){var level=copy.req.Defence;copy.req=Object.assign({},copy.req);delete copy.req.Defence;copy.req[cls==='ranger'?'Ranged':cls==='mage'?'Magic':'Summoning']=level}return copy}
legacySharedGear.forEach(function(name){var base=itemDB[name];['warrior','ranger','mage','summoner'].forEach(function(cls){var copy=specialiseLegacyGear(base,cls);copy.legacySource=name;itemDB[classGearName(name,cls)]=copy});base.legacyShared=true});
function migrateSharedGear(){if(!save)return;var targetVersion=2,needsVersion=(Number(save.sharedGearMigrationVersion)||0)<targetVersion,changed=false;legacySharedGear.forEach(function(name){var qty=(save.items&&Number(save.items[name])||0)+(save.bank&&Number(save.bank[name])||0);if(qty>0){['warrior','ranger','mage','summoner'].forEach(function(cls){var nn=classGearName(name,cls);save.bank[nn]=(Number(save.bank[nn])||0)+qty});save.items[name]=0;save.bank[name]=0;changed=true}['warrior','ranger','mage','summoner'].forEach(function(cls){var eq=save.equipment&&save.equipment[cls];if(eq)Object.keys(eq).forEach(function(slot){if(eq[slot]===name){eq[slot]=classGearName(name,cls);changed=true}})})});if(needsVersion||changed){save.sharedGearMigrationVersion=targetVersion;save.sharedGearMigrated=true}}
function grantEquipmentReward(name,qty,label){qty=Math.max(1,Number(qty)||1);var it=itemDB[name];if(it&&it.legacyShared){var names=[];['warrior','ranger','mage','summoner'].forEach(function(cls){var nn=classGearName(name,cls);save.items[nn]=(Number(save.items[nn])||0)+qty;names.push(nn)});save.collection[name]=true;if(label)save.drops.push(label+': '+name+' → 4 class variants');return names}save.items[name]=(Number(save.items[name])||0)+qty;save.collection[name]=true;if(label)save.drops.push(label+': '+name);return [name]}

