function nextPerkTask(exclude){var pool=perkTaskPool.filter(perkTaskEligible).filter(function(t){return !exclude.includes(t.id)});if(!pool.length)return null;var tierMax=save.perks.level>=65?4:save.perks.level>=40?3:save.perks.level>=20?2:1;var ranks={Standard:1,Hard:2,Elite:3,Legendary:4},weighted=pool.filter(function(t){return (ranks[t.tier]||1)<=tierMax});if(weighted.length)pool=weighted;return pool[Math.floor(Math.random()*pool.length)].id}
