window.buyPerk=buyPerk;
function togglePerk(id){if(!perkShop[id]||perkShop[id].keystone||!save.perks.unlocked.includes(id))return;var i=save.perks.equipped.indexOf(id);if(i>=0)save.perks.equipped.splice(i,1);else if(save.perks.equipped.length<perkSlots())save.perks.equipped.push(id);else{alert('All perk slots are full.');return}persist()}
function hasPerk(id){return save.perks.equipped.includes(id)||save.perks.level>=50&&save.perks.keystone===id}
function toggleKeystone(id){var p=perkShop[id];if(!p||!p.keystone||!save.perks.unlocked.includes(id))return;if(save.perks.level<50){alert('Keystone slot unlocks at Perk Level 50.');return}save.perks.equipped=save.perks.equipped.filter(function(x){return x!==id});save.perks.keystone=save.perks.keystone===id?null:id;persist()}
