let gathering=null,gatherStart=0,gatherTimer=null;
function startGathering(type){let g=gatherDB[type];if(!g)return;if(save.skills[g.skill].lvl<g.level){msg('You need '+g.skill+' level '+g.level+'.');return}if(type==='bronze'&&(save.bank['Copper ore']<1||save.bank['Tin ore']<1)){msg('You need Copper and Tin ore to start smelting.');return}if(type==='frostbar'&&save.bank['Frostsilver ore']<2){msg('You need 2 Frostsilver ore to start smelting.');return}if(type==='ironbar'&&save.bank['Ironvale ore']<2){msg('You need 2 Ironvale ore to start smelting.');return}if(type==='bogbar'&&save.bank['Bogiron ore']<2){msg('You need 2 Bogiron ore to start smelting.');return}if(type==='moonbar'&&(save.bank['Moonstone ore']||0)<2){msg('You need 2 Moonstone ore to start smelting.');return}stopGathering(false);gathering=type;gatherStart=performance.now();activityName.textContent=g.verb;activityText.textContent='Gathering automatically...';stopGather.disabled=false;gatherTimer=setInterval(()=>completeGather(type),g.time*(hasPerk('quickhands')||hasPerk('mastergatherer')?.9:1));renderGatherProgress()}
function completeGather(type){if(gathering!==type)return;let g=gatherDB[type];if(type==='bronze'){if(save.bank['Copper ore']<1||save.bank['Tin ore']<1){msg('Smelting stopped: you ran out of Copper or Tin ore.');stopGathering();renderUIPreservingMenus();return}save.bank['Copper ore']--;save.bank['Tin ore']--;save.bank['Bronze bar']++;addXP('Smithing',12);trackSmeltMastery('bronze');gatherStart=performance.now();msg('You smelt 1 Bronze bar.');renderUIPreservingMenus();return}if(type==='frostbar'){if(save.bank['Frostsilver ore']<2){msg('Smelting stopped: you need 2 Frostsilver ore.');stopGathering();renderUIPreservingMenus();return}save.bank['Frostsilver ore']-=2;save.bank['Frostsilver bar']++;addXP('Smithing',65);trackSmeltMastery('frostbar');gatherStart=performance.now();msg('You smelt 1 Frostsilver bar.');renderUIPreservingMenus();return}if(type==='ironbar'){if(save.bank['Ironvale ore']<2){msg('Smelting stopped: you need 2 Ironvale ore.');stopGathering();renderUIPreservingMenus();return}save.bank['Ironvale ore']-=2;save.bank['Ironvale bar']++;addXP('Smithing',30);trackSmeltMastery('ironbar');gatherStart=performance.now();msg('You smelt 1 Ironvale bar.');renderUIPreservingMenus();return}if(type==='bogbar'){if(save.bank['Bogiron ore']<2){msg('Smelting stopped: you need 2 Bogiron ore.');stopGathering();renderUIPreservingMenus();return}save.bank['Bogiron ore']-=2;save.bank['Bogiron bar']=(save.bank['Bogiron bar']||0)+1;addXP('Smithing',95);trackSmeltMastery('bogbar');gatherStart=performance.now();msg('You smelt 1 Bogiron bar.');renderUIPreservingMenus();return}if(type==='moonbar'){if((save.bank['Moonstone ore']||0)<2){msg('Smelting stopped: you need 2 Moonstone ore.');stopGathering();renderUIPreservingMenus();return}save.bank['Moonstone ore']-=2;save.bank['Moonstone bar']=(save.bank['Moonstone bar']||0)+1;addXP('Smithing',135);trackSmeltMastery('moonbar');gatherStart=performance.now();msg('You smelt 1 Moonstone bar.');renderUIPreservingMenus();return}var qty=1;var doubleChance=hasPerk('mastergatherer')?.10:0;if(hasPerk('resourcefulkey')&&['Mining','Woodcutting','Fishing'].includes(g.skill))doubleChance+=.15;if(g.skill==='Mining')doubleChance+=hasPerk('mastermine')?.40:hasPerk('pickaxe')?.30:0;if(g.skill==='Woodcutting')doubleChance+=hasPerk('masterwood')?.40:hasPerk('lumberjack')?.30:0;if(g.skill==='Fishing')doubleChance+=hasPerk('masterfish')?.40:hasPerk('angler')?.30:0;if(Math.random()<doubleChance)qty=2;if((g.skill==='Mining'&&masteryPassive('mining'))||(g.skill==='Woodcutting'&&masteryPassive('woodcutting'))||(g.skill==='Fishing'&&masteryPassive('fishing'))){if(Math.random()<.15){qty++;if(maxMasteryPassive()&&maxCapeEquipped()&&Math.random()<.05)qty++}}if(bossMasteryPassive('tyrant')&&['ironore'].includes(type)&&Math.random()<.15)qty++;if(bossMasteryPassive('frostwyrm')&&g.skill==='Fishing'&&['frostsalmon'].includes(type)&&Math.random()<.15)qty++;if(bossMasteryPassive('mirequeen')&&['bogiron','rotwood'].includes(type)&&Math.random()<.15)qty++;if(bossMasteryPassive('moonweaver')&&type==='moonstone'&&Math.random()<.10)qty++;save.bank[g.item]=(save.bank[g.item]||0)+qty;addXP(g.skill,g.xp*qty);trackGatherMastery(type,g,qty);questSkillAction(g.skill,type,qty);if(g.skill==='Mining'){addPerkProgress('mine',qty);if(type==='moonstone')addPerkProgress('moonstonemine',qty)}else if(g.skill==='Fishing'){addPerkProgress('fish',qty);if(type==='moonfin')addPerkProgress('moonfinfish',qty)}else if(g.skill==='Woodcutting'){addPerkProgress('wood',qty);if(type==='glowbark')addPerkProgress('glowbarkwood',qty)}gatherStart=performance.now();msg(qty===2?'SKILLING PERK! Double '+g.item+' + double XP.':'You gather 1 '+g.item+'.');renderUIPreservingMenus()}
function stopGathering(show=true){if(gatherTimer)clearInterval(gatherTimer);gatherTimer=null;gathering=null;if(window.activityName)activityName.textContent='Not currently gathering';if(window.activityText)activityText.textContent=show?'Gathering stopped.':'Choose a resource below.';if(window.stopGather)stopGather.disabled=true;if(window.activityProgress)activityProgress.querySelector('i').style.width='0%'}
function renderGatherProgress(){if(!gathering)return;let g=gatherDB[gathering],pct=Math.min(100,(performance.now()-gatherStart)/g.time*100);if(window.activityProgress)activityProgress.querySelector('i').style.width=pct+'%';requestAnimationFrame(renderGatherProgress)}
window.startGathering=startGathering;window.stopGathering=stopGathering;
function skillingDisplayXp(skill,base){return Math.round(base*(skill==='Summoning'||['Attack','Strength','Defence','Ranged','Magic','Hitpoints'].includes(skill)?3.5:3))}
function syncStaticSkillingCards(){
 var panes={
  mining:['copper','tin','ironore','frostsilver','bogiron','moonstone'],
  woodcutting:['logs','oak','frostpine','rotwood','glowbark'],
  smelting:['bronze','ironbar','frostbar','bogbar','moonbar'],
  fishing:['minnow','trout','pike','frostsalmon','moonfin']
 };
 Object.keys(panes).forEach(function(pane){
  var root=document.querySelector('#workshop-'+pane);if(!root)return;
  var cards=root.querySelectorAll('.activityList>.card');
  panes[pane].forEach(function(key,i){var g=gatherDB[key],card=cards[i];if(!g||!card)return;var p=card.querySelector('p');if(!p)return;
   var xp=skillingDisplayXp(g.skill,g.xp),sec=(g.time/1000).toFixed(1).replace(/\.0$/,'');
   if(pane==='smelting'){var cost=key==='bronze'?'1 Copper ore + 1 Tin ore':key==='ironbar'?'2 Ironvale ore':key==='frostbar'?'2 Frostsilver ore':key==='bogbar'?'2 Bogiron ore':'2 Moonstone ore';p.textContent=cost+' • Smithing Lv '+g.level+' • '+xp+' XP • '+sec+' sec'}
   else p.textContent=g.skill+' Lv '+g.level+' • '+xp+' XP • '+sec+' sec'
  })
 });
 var cookRoot=document.querySelector('#workshop-cooking');if(cookRoot){var cookKeys=['minnow','trout','pike','frostsalmon','moonfin'],cookCards=cookRoot.querySelectorAll('.activityList>.card');cookKeys.forEach(function(key,i){var r=cookDB[key],card=cookCards[i];if(!r||!card)return;var p=card.querySelector('p');if(p)p.textContent='Cooking Lv '+r.level+' • '+skillingDisplayXp('Cooking',r.xp)+' XP • '+(r.time/1000).toFixed(1).replace(/\.0$/,'')+' sec'})}
}
syncStaticSkillingCards();
let smithingKey=null,smithTimer=null,smithStart=0;
function startSmithing(key){let r=recipes[key];if(!r)return;if(save.skills.Smithing.lvl<r.level){msg('You need Smithing level '+r.level+'.');return}if((save.bank[r.resource]||0)<r.bars){msg('You need '+r.bars+' '+r.resource+(r.bars>1?'s':'')+'.');return}stopGathering(false);stopSmithing(false);smithingKey=key;smithStart=performance.now();activityName.textContent='Smithing '+r.name;activityText.textContent='Producing automatically...';stopGather.disabled=false;smithTimer=setInterval(()=>completeSmithing(key),r.time*(hasPerk('quickhands')?.9:1));renderSmithProgress()}
function completeSmithing(key){if(smithingKey!==key)return;let r=recipes[key];if((save.bank[r.resource]||0)<r.bars){msg('Smithing stopped: not enough '+r.resource+'.');stopSmithing();renderUIPreservingMenus();return}var preserveSmith=masteryPassive('smithing')&&Math.random()<.10;if(preserveSmith&&masterySurge())save.bank[r.resource]=(save.bank[r.resource]||0)+r.bars;if(!preserveSmith)save.bank[r.resource]-=r.bars;var smithQty=((hasPerk('mastersmith')&&Math.random()<.35)||(hasPerk('smith')&&Math.random()<.30))?2:1;save.items[r.name]=(save.items[r.name]||0)+smithQty;questCraft(r.name,smithQty);questSkillAction('Smithing',key,smithQty);addXP('Smithing',r.xp*smithQty);trackSmithingMastery(r,smithQty);addPerkProgress('smith',smithQty);smithStart=performance.now();msg(smithQty===2?'EFFICIENT SMITH! 2 '+r.name+' + double XP.':'You smith 1 '+r.name+'.');renderUIPreservingMenus()}
function stopSmithing(show=true){if(smithTimer)clearInterval(smithTimer);smithTimer=null;smithingKey=null;if(show&&window.activityName){activityName.textContent='Not currently gathering';activityText.textContent='Smithing stopped.';stopGather.disabled=true;activityProgress.querySelector('i').style.width='0%'}}
function renderSmithProgress(){if(!smithingKey)return;let r=recipes[smithingKey],pct=Math.min(100,(performance.now()-smithStart)/r.time*100);activityProgress.querySelector('i').style.width=pct+'%';requestAnimationFrame(renderSmithProgress)}
const oldStopGather=stopGathering;stopGathering=function(show=true){oldStopGather(show);if(smithingKey)stopSmithing(show)}
window.startSmithing=startSmithing;
function equipItem(name,targetClass){
 let it=itemDB[name],owned=(save.items[name]||0)+(save.bank[name]||0);if(!it||owned<=0||it.legacyShared)return;
 if(it.req){for(const [skill,lvl] of Object.entries(it.req))if(save.skills[skill].lvl<lvl){alert(name+' requires '+skill+' level '+lvl+'.');return}}
 const cls=it.class==='all'?targetClass:it.class;
 if(!['warrior','ranger','mage','summoner'].includes(cls)){alert('Choose which class should equip this item.');return}
 save.equipment[cls][it.slot]=name;persist();
}window.equipItem=equipItem;


