{id:'lunarwardens',name:'Sentinels of Lunara',npc:'Astral Seer Lyra',story:'The Lunar Court has sealed its causeways. Lyra asks you to break through the sentinels before the Moonweaver completes her ritual.',req:()=>save.quests.completed.includes('lunaraarrival'),objective:'Defeat 20 Lunar Sentinels, 15 Starweavers and 10 Astral Golems',done:()=>qkill('lunarsentinel')>=20&&qkill('starweaver')>=15&&qkill('astralgolem')>=10,reward:'45,000 coins + 20 Moonstone bars + 24 Lunar Thread + 8,250 Magic XP + 8,250 Summoning XP',give:()=>{save.coins+=45000;save.bank['Moonstone bar']=(save.bank['Moonstone bar']||0)+20;save.bank['Lunar Thread']=(save.bank['Lunar Thread']||0)+24;addXP('Magic',5500);addXP('Summoning',5500)}},
{id:'moonweaverquest',name:'Eclipse at the Lunar Court',npc:'Astral Seer Lyra',story:'The Moonweaver has begun the eclipse. If the Lunar Court falls completely under her spell, the dream realm will spill into Realmforge.',req:()=>save.quests.completed.includes('lunarwardens')&&save.campaign.unlocked>=25,objective:'Defeat the Moonweaver',done:()=>save.campaign.moonBossKills>=1,reward:'60,000 coins + 25 Moonstone bars + 30 Lunar Thread + 300 Hunter Points + 10,500 Combat XP',give:()=>{save.coins+=60000;save.bank['Moonstone bar']=(save.bank['Moonstone bar']||0)+25;save.bank['Lunar Thread']=(save.bank['Lunar Thread']||0)+30;save.hunter.points+=300;['Magic','Summoning','Hitpoints'].forEach(x=>addXP(x,3500))}},
{id:'dreamingquest',name:'Into the Dreaming Hollow',npc:'Astral Seer Lyra',story:'The Moonweaver was holding something back. The Dream Eater now stirs beneath Lunara, feeding on the fractured dreams of the realm.',req:()=>save.quests.completed.includes('moonweaverquest')&&dreamingHollowUnlocked(),objective:'Complete Dreaming Hollow and defeat the Dream Eater',done:()=>save.dungeon.dreamingHollow.completions>=1,reward:'80,000 coins + 30 Moonstone bars + 35 Lunar Thread + 400 Hunter Points + 12,000 Magic XP + 12,000 Summoning XP',give:()=>{save.coins+=80000;save.bank['Moonstone bar']=(save.bank['Moonstone bar']||0)+30;save.bank['Lunar Thread']=(save.bank['Lunar Thread']||0)+35;save.hunter.points+=400;addXP('Magic',8000);addXP('Summoning',8000)}},
{id:'minerspath',name:'Prospector of Greenvale',npc:'Miner Brann',story:'Brann wants proof that you can work a seam instead of merely swinging a pickaxe.',req:()=>save.skills.Mining.lvl>=5,objective:'Mine 50 ore',done:()=>qcraft('skill:mining')>=50,reward:'4,000 coins + 20 Copper ore + 20 Tin ore + 1,500 Mining XP',give:()=>{save.coins+=4000;save.bank['Copper ore']+=20;save.bank['Tin ore']+=20;addXP('Mining',1000)}},
{id:'deepminer',name:'Ore of the Realms',npc:'Miner Brann',story:'The deeper regions hold metals that make Greenvale copper look like river stone.',req:()=>save.skills.Mining.lvl>=35&&save.campaign.unlocked>=16,objective:'Mine 40 Frostsilver ore and 40 Bogiron ore',done:()=>qcraft('skill:mining:frostsilver')>=40&&qcraft('skill:mining:bogiron')>=40,reward:'18,000 coins + 20 Frostsilver ore + 20 Bogiron ore + 6,000 Mining XP',give:()=>{save.coins+=18000;save.bank['Frostsilver ore']=(save.bank['Frostsilver ore']||0)+20;save.bank['Bogiron ore']=(save.bank['Bogiron ore']||0)+20;addXP('Mining',4000)}},
{id:'moonminer',name:'Moonstone Prospector',npc:'Astral Smith Neris',story:'Neris needs a miner who can recognise living Moonstone before its light fades.',req:()=>save.skills.Mining.lvl>=50&&save.campaign.unlocked>=21,objective:'Mine 75 Moonstone ore',done:()=>qcraft('skill:mining:moonstone')>=75,reward:'35,000 coins + 25 Moonstone ore + 10,500 Mining XP',give:()=>{save.coins+=35000;save.bank['Moonstone ore']=(save.bank['Moonstone ore']||0)+25;addXP('Mining',7000)}},
{id:'masterforge',name:'Forged Through Fire',npc:'Smith Torren',story:'Torren has heard of your work. Now he wants equipment forged from metals gathered beyond Greenvale.',req:()=>save.skills.Smithing.lvl>=25,objective:'Smith 40 equipment pieces',done:()=>qcraft('skill:smithing')>=40,reward:'16,000 coins + 20 Ironvale bars + 6,000 Smithing XP',give:()=>{save.coins+=16000;save.bank['Ironvale bar']=(save.bank['Ironvale bar']||0)+20;addXP('Smithing',4000)}},
{id:'moonforge',name:'The Lunar Forge',npc:'Astral Smith Neris',story:'Moonstone is difficult to shape. Neris challenges you to prove that the Lunar Forge answers to your hammer.',req:()=>save.skills.Smithing.lvl>=50&&save.campaign.unlocked>=21,objective:'Smith 50 equipment pieces',done:()=>qcraft('skill:smithing')>=50,reward:'40,000 coins + 25 Moonstone bars + 12,000 Smithing XP',give:()=>{save.coins+=40000;save.bank['Moonstone bar']=(save.bank['Moonstone bar']||0)+25;addXP('Smithing',8000)}},
{id:'forestersoath',name:'The Forester\'s Oath',npc:'Forester Hale',story:'Hale teaches that every timber has a purpose, from Greenvale logs to the ancient woods beyond the mire.',req:()=>save.skills.Woodcutting.lvl>=10,objective:'Chop 75 logs',done:()=>qcraft('skill:woodcutting')>=75,reward:'6,000 coins + 25 Oakheart logs + 2,250 Woodcutting XP',give:()=>{save.coins+=6000;save.bank['Oakheart logs']=(save.bank['Oakheart logs']||0)+25;addXP('Woodcutting',1500)}},
{id:'glowbarkquest',name:'Light Beneath the Bark',npc:'Astral Seer Lyra',story:'Glowbark stores Lunara\'s moonlight within its grain. Lyra needs branches cut without extinguishing their glow.',req:()=>save.skills.Woodcutting.lvl>=48&&save.campaign.unlocked>=21,objective:'Chop 75 Glowbark logs',done:()=>qcraft('skill:woodcutting:glowbark')>=75,reward:'32,000 coins + 25 Glowbark logs + 10,500 Woodcutting XP',give:()=>{save.coins+=32000;save.bank['Glowbark logs']=(save.bank['Glowbark logs']||0)+25;addXP('Woodcutting',7000)}},
{id:'riverprovisioner',name:'Provision the Wardens',npc:'Cook Mara',story:'Mara needs a steady supply of fish for the wardens patrolling Greenvale.',req:()=>save.skills.Fishing.lvl>=5&&save.skills.Cooking.lvl>=5,objective:'Catch 50 fish and successfully cook 40 fish',done:()=>qcraft('skill:fishing')>=50&&qcraft('skill:cooking')>=40,reward:'7,500 coins + 2,250 Fishing XP + 2,250 Cooking XP',give:()=>{save.coins+=7500;addXP('Fishing',1500);addXP('Cooking',1500)}},
{id:'moonfinquest',name:'Feast of Moonlight',npc:'Cook Mara',story:'Moonfin are said to taste different under every phase of Lunara\'s sky. Mara wants enough for a true lunar feast.',req:()=>save.skills.Fishing.lvl>=48&&save.skills.Cooking.lvl>=48&&save.campaign.unlocked>=21,objective:'Catch 60 Moonfin and successfully cook 50 Moonfin',done:()=>qcraft('skill:fishing:moonfin')>=60&&qcraft('skill:cooking:moonfin')>=50,reward:'38,000 coins + 20 Raw Moonfin + 12,000 Fishing XP + 12,000 Cooking XP',give:()=>{save.coins+=38000;save.bank['Raw Moonfin']=(save.bank['Raw Moonfin']||0)+20;addXP('Fishing',8000);addXP('Cooking',8000)}},
{id:'fletchersmark',name:'The Fletcher\'s Mark',npc:'Ranger Sera',story:'Sera judges a ranger by the equipment they can make as much as the arrows they loose.',req:()=>save.skills.Fletching.lvl>=10,objective:'Fletch 30 Ranger supplies',done:()=>qcraft('skill:fletching')>=30,reward:'9,000 coins + 30 Oakheart logs + 3,750 Fletching XP',give:()=>{save.coins+=9000;save.bank['Oakheart logs']=(save.bank['Oakheart logs']||0)+30;addXP('Fletching',2500)}},
{id:'masterfletcher',name:'Moonstrung',npc:'Ranger Sera',story:'Lunara materials can hold impossible tension. Sera wants to see what an experienced fletcher can make from them.',req:()=>save.skills.Fletching.lvl>=45&&save.campaign.unlocked>=21,objective:'Fletch 60 Ranger supplies',done:()=>qcraft('skill:fletching')>=60,reward:'34,000 coins + 25 Glowbark logs + 25 Lunar Thread + 10,500 Fletching XP',give:()=>{save.coins+=34000;save.bank['Glowbark logs']=(save.bank['Glowbark logs']||0)+25;save.bank['Lunar Thread']=(save.bank['Lunar Thread']||0)+25;addXP('Fletching',7000)}},
{id:'artisanspath',name:'Threads of the Realm',npc:'Artisan Vessa',story:'Vessa believes a true artisan should be able to turn the strange materials of every region into something useful.',req:()=>save.skills.Crafting.lvl>=10,objective:'Craft 30 items',done:()=>qcraft('skill:crafting')>=30,reward:'9,000 coins + 18 Ash Thread + 3,750 Crafting XP',give:()=>{save.coins+=9000;save.bank['Ash Thread']=(save.bank['Ash Thread']||0)+18;addXP('Crafting',2500)}},
{id:'lunarweaverquest',name:'Weaver of Moonlight',npc:'Artisan Vessa',story:'Lunar Thread refuses ordinary hands. Vessa challenges you to master the material that binds Lunara\'s finest equipment.',req:()=>save.skills.Crafting.lvl>=48&&save.campaign.unlocked>=21,objective:'Craft 50 items',done:()=>qcraft('skill:crafting')>=50,reward:'36,000 coins + 30 Lunar Thread + 12 Lunarweave Cloth + 10,500 Crafting XP',give:()=>{save.coins+=36000;save.bank['Lunar Thread']=(save.bank['Lunar Thread']||0)+30;save.bank['Lunarweave Cloth']=(save.bank['Lunarweave Cloth']||0)+12;addXP('Crafting',7000)}}
