{id:'battletraining',name:'Lessons of the Battlefield',npc:'Captain Rowan',story:'Rowan wants every tower commander to understand the strengths of the three original disciplines.',req:()=>true,objective:'Defeat 75 enemies with Warrior, 75 with Ranger and 75 with Mage towers',done:()=>save.quests.combat.warrior>=75&&save.quests.combat.ranger>=75&&save.quests.combat.mage>=75,reward:'12,000 coins + 3,000 Attack XP + 3,000 Ranged XP + 3,000 Magic XP',give:()=>{save.coins+=12000;addXP('Attack',2000);addXP('Ranged',2000);addXP('Magic',2000)}},
{id:'elitebreaker',name:'Break the Elite',npc:'Captain Rowan',story:'Elite creatures are beginning to lead the ordinary ranks. Rowan needs a commander capable of removing them quickly.',req:()=>save.campaign.unlocked>=6,objective:'Defeat 50 Elite enemies',done:()=>save.quests.combat.elites>=50,reward:'24,000 coins + 6,000 Strength XP + 6,000 Defence XP + 6,000 Hitpoints XP',give:()=>{save.coins+=24000;addXP('Strength',4000);addXP('Defence',4000);addXP('Hitpoints',4000)}},
{id:'summonerawakening',name:'Call of the First Spirit',npc:'Spiritbinder Orin',story:'Orin believes the spirits answer only commanders who fight beside their summons rather than hiding behind them.',req:()=>save.skills.Summoning.lvl>=5,objective:'Defeat 100 enemies with Summoner towers',done:()=>save.quests.combat.summoner>=100,reward:'15,000 coins + 25 Spirit Shards + 6,000 Summoning XP',give:()=>{save.coins+=15000;save.bank['Spirit Shard']=(save.bank['Spirit Shard']||0)+25;addXP('Summoning',4000)}},
{id:'spiritcommander',name:'Commander of Spirits',npc:'Spiritbinder Orin',story:'Your bond has strengthened. Orin now asks you to command spirits against the strongest creatures in the realm.',req:()=>save.skills.Summoning.lvl>=35&&save.campaign.unlocked>=16,objective:'Defeat 400 enemies with Summoner towers',done:()=>save.quests.combat.summoner>=400,reward:'35,000 coins + 50 Spirit Shards + 2 Ancient Spirit Cores + 12,000 Summoning XP',give:()=>{save.coins+=35000;save.bank['Spirit Shard']=(save.bank['Spirit Shard']||0)+50;save.bank['Ancient Spirit Core']=(save.bank['Ancient Spirit Core']||0)+2;addXP('Summoning',8000)}},
{id:'fourdisciplines',name:'Four Disciplines',npc:'Warden Elira',story:'Realmforge now fights with blade, bow, spell and spirit. Elira wants proof that none of the four disciplines has been neglected.',req:()=>save.campaign.unlocked>=21,objective:'Defeat 300 enemies with each tower class',done:()=>['warrior','ranger','mage','summoner'].every(k=>(Number(save.quests.combat[k])||0)>=300),reward:'55,000 coins + 7,500 Attack XP + 7,500 Ranged XP + 7,500 Magic XP + 7,500 Summoning XP',give:()=>{save.coins+=55000;addXP('Attack',5000);addXP('Ranged',5000);addXP('Magic',5000);addXP('Summoning',5000)}},
{id:'hunterinitiate',name:'Guild Initiation',npc:'Hunter Maelis',story:'Maelis does not care how many monsters you have slain. The Guild values discipline: take an assignment and finish the job.',req:()=>save.skills['Monster Hunter'].lvl>=1,objective:'Complete 3 Hunter Guild assignments',done:()=>save.quests.combat.hunterAssignments>=3,reward:'10,000 coins + 150 Hunter Points + 4,500 Monster Hunter XP',give:()=>{save.coins+=10000;save.hunter.points+=150;addXP('Monster Hunter',3000)}},
{id:'hunterveteranquest',name:'Contract Veteran',npc:'Hunter Maelis',story:'Routine contracts no longer test you. Maelis has marked more dangerous targets for proven hunters.',req:()=>save.hunter.unlocks.veteran||save.hunter.unlocks.elite,objective:'Complete 10 Hunter Guild assignments',done:()=>save.quests.combat.hunterAssignments>=10,reward:'25,000 coins + 300 Hunter Points + 9,000 Monster Hunter XP',give:()=>{save.coins+=25000;save.hunter.points+=300;addXP('Monster Hunter',6000)}},
{id:'hunterelitequest',name:'Marked for the Elite',npc:'Hunter Maelis',story:'Elite contracts are where hunters earn their names. Survive enough of them and the Guild will remember yours.',req:()=>save.hunter.unlocks.elite||save.hunter.unlocks.veteran,objective:'Complete 8 Elite-or-higher Hunter assignments',done:()=>save.quests.combat.eliteHunterAssignments>=8,reward:'45,000 coins + 500 Hunter Points + 15,000 Monster Hunter XP',give:()=>{save.coins+=45000;save.hunter.points+=500;addXP('Monster Hunter',10000)}},
{id:'bosshunter1',name:'Five Crowns, Five Foes',npc:'Warden Elira',story:'Every region has produced a champion of its corruption. Elira wants each of the five campaign bosses defeated.',req:()=>save.campaign.unlocked>=25,objective:'Defeat Goblin Warlord, Ember Tyrant, Frost Wyrm, Mire Queen and Moonweaver at least once',done:()=>save.campaign.bossKills>=1&&save.campaign.ashenBossKills>=1&&save.campaign.frostBossKills>=1&&save.campaign.mireBossKills>=1&&save.campaign.moonBossKills>=1,reward:'65,000 coins + 600 Hunter Points + 12,000 Hitpoints XP',give:()=>{save.coins+=65000;save.hunter.points+=600;addXP('Hitpoints',8000)}},
{id:'bosshunter25',name:'Veteran of the Five',npc:'Warden Elira',story:'One victory can be luck. Repeated victories prove mastery over every threat Realmforge has faced.',req:()=>save.quests.completed.includes('bosshunter1'),objective:'Reach 10 kills on each campaign boss',done:()=>save.campaign.bossKills>=10&&save.campaign.ashenBossKills>=10&&save.campaign.frostBossKills>=10&&save.campaign.mireBossKills>=10&&save.campaign.moonBossKills>=10,reward:'120,000 coins + 1,000 Hunter Points + 20,000 Attack XP + 20,000 Ranged XP + 20,000 Magic XP + 20,000 Summoning XP',give:()=>{save.coins+=120000;save.hunter.points+=1000;addXP('Attack',Math.round(20000/1.5));addXP('Ranged',Math.round(20000/1.5));addXP('Magic',Math.round(20000/1.5));addXP('Summoning',Math.round(20000/1.5))}}
