{id:'ashenfallsquest',name:'Trial by Inferno',npc:'Keeper Moss',story:'The roots beneath Greenvale lead toward a furnace-hot chamber under Ashen Peaks. Moss fears an Infernal Warden has claimed it.',req:()=>save.quests.completed.includes('tyrant')&&ashenFallsUnlocked(),objective:'Complete Ashen Falls once',done:()=>save.dungeon.ashenFalls.completions>=1,reward:'18,000 coins + 15 Ironvale bars + 12 Ashweave Cloth + 5,250 Hitpoints XP',give:()=>{save.coins+=18000;save.bank['Ironvale bar']=(save.bank['Ironvale bar']||0)+15;save.bank['Ashweave Cloth']=(save.bank['Ashweave Cloth']||0)+12;addXP('Hitpoints',3500)}},
{id:'dungeonpathfinder',name:'Pathfinder of the Depths',npc:'Keeper Veyra',story:'Every region hides a place more dangerous than its roads. Veyra asks you to prove you can survive them all.',req:()=>dreamingHollowUnlocked(),objective:'Complete each regional dungeon at least once',done:()=>save.dungeon.completions>=1&&save.dungeon.ashenFalls.completions>=1&&save.dungeon.frozenCrypt.completions>=1&&save.dungeon.drownedTemple.completions>=1&&save.dungeon.dreamingHollow.completions>=1,reward:'75,000 coins + 500 Hunter Points + 12,000 Defence XP + 12,000 Hitpoints XP',give:()=>{save.coins+=75000;save.hunter.points+=500;addXP('Defence',8000);addXP('Hitpoints',8000)}},
{id:'dungeonveteran',name:'Veteran Delver',npc:'Keeper Veyra',story:'A single descent teaches caution. Repeated descents teach mastery.',req:()=>save.quests.completed.includes('dungeonpathfinder'),objective:'Reach 5 clears in every regional dungeon',done:()=>save.dungeon.completions>=5&&save.dungeon.ashenFalls.completions>=5&&save.dungeon.frozenCrypt.completions>=5&&save.dungeon.drownedTemple.completions>=5&&save.dungeon.dreamingHollow.completions>=5,reward:'140,000 coins + 1,000 Hunter Points + 25 Moonstone bars + 18,000 Defence XP + 18,000 Hitpoints XP',give:()=>{save.coins+=140000;save.hunter.points+=1000;save.bank['Moonstone bar']=(save.bank['Moonstone bar']||0)+25;addXP('Defence',12000);addXP('Hitpoints',12000)}},
{id:'flawlessdelver',name:'Untouched by the Depths',npc:'Captain Rowan',story:'Rowan calls survival an achievement. Returning without a single life lost is something else entirely.',req:()=>save.quests.completed.includes('dungeonpathfinder'),objective:'Complete 3 dungeons without losing a life',done:()=>save.quests.activities.flawlessDungeons>=3,reward:'90,000 coins + 600 Hunter Points + 15,000 Defence XP',give:()=>{save.coins+=90000;save.hunter.points+=600;addXP('Defence',10000)}},
{id:'dungeonmaster',name:'Master of the Depths',npc:'Keeper Veyra',story:'The creatures below now know your name. Veyra has one final test: prove the depths can no longer break you.',req:()=>save.quests.completed.includes('dungeonveteran'),objective:'Complete 25 dungeons in total',done:()=>save.quests.activities.dungeons>=25,reward:'180,000 coins + 1,250 Hunter Points + 30 Lunar Thread + 24,000 Hitpoints XP',give:()=>{save.coins+=180000;save.hunter.points+=1250;save.bank['Lunar Thread']=(save.bank['Lunar Thread']||0)+30;addXP('Hitpoints',16000)}},
{id:'raidfirstbreach',name:'Breach the Shattered Citadel',npc:'Citadel Scout Kael',story:'A fractured fortress has appeared beyond the known roads. Kael needs a commander willing to enter before its gates stabilise.',req:()=>save.campaign.cleared.includes(24),objective:'Complete the Shattered Citadel raid once',done:()=>save.raid.completions>=1,reward:'100,000 coins + 150 Raid Tokens + 12,000 Attack XP + 12,000 Ranged XP + 12,000 Magic XP + 12,000 Summoning XP',give:()=>{save.coins+=100000;save.raid.tokens=(save.raid.tokens||0)+150;['Attack','Ranged','Magic','Summoning'].forEach(x=>addXP(x,8000))}},
{id:'raidveteran',name:'Citadel Veteran',npc:'Citadel Scout Kael',story:'The Citadel rebuilds itself after every defeat. Kael wants proof that its shifting halls cannot stop you.',req:()=>save.quests.completed.includes('raidfirstbreach'),objective:'Complete the Shattered Citadel 5 times',done:()=>save.raid.completions>=5,reward:'200,000 coins + 300 Raid Tokens + 30,000 Hitpoints XP',give:()=>{save.coins+=200000;save.raid.tokens=(save.raid.tokens||0)+300;addXP('Hitpoints',20000)}},
{id:'raidflawless',name:'Unbroken Citadel Run',npc:'Citadel Scout Kael',story:'The Citadel Lord expects every intruder to bleed before reaching the throne. Prove him wrong.',req:()=>save.quests.completed.includes('raidfirstbreach'),objective:'Complete a raid without losing a life',done:()=>save.quests.activities.flawlessRaids>=1,reward:'175,000 coins + 250 Raid Tokens + 24,000 Defence XP',give:()=>{save.coins+=175000;save.raid.tokens=(save.raid.tokens||0)+250;addXP('Defence',16000)}},
{id:'raidmaster',name:'Breaker of the Citadel',npc:'Citadel Scout Kael',story:'The Citadel has fallen before you again and again. One final campaign will establish your command beyond question.',req:()=>save.quests.completed.includes('raidveteran'),objective:'Complete the Shattered Citadel 10 times',done:()=>save.raid.completions>=10,reward:'350,000 coins + 500 Raid Tokens + 40 Lunar Thread + 30,000 Attack XP + 30,000 Ranged XP + 30,000 Magic XP + 30,000 Summoning XP',give:()=>{save.coins+=350000;save.raid.tokens=(save.raid.tokens||0)+500;save.bank['Lunar Thread']=(save.bank['Lunar Thread']||0)+40;['Attack','Ranged','Magic','Summoning'].forEach(x=>addXP(x,20000))}}
