function hunterTargetMaps(kind){var out=[];for(var i=0;i<maps.length;i++){var m=maps[i];if(m&&m.kinds&&m.kinds.includes(kind)&&i<save.campaign.unlocked&&(!m.req||combatLevel()>=m.req))out.push(i)}return out}
