 if(!pool.length)pool=available.slice().sort(function(a,b){return b.level-a.level}).slice(0,Math.min(5,available.length));
 let t=pool[Math.floor(Math.random()*pool.length)],amount=t.min+Math.floor(Math.random()*(t.max-t.min+1));
