function hunterKill(kind){let t=save.hunter.task;if(!t||t.kind!==kind)return;t.done++;addMasteryProgress('hunter','assignedKills',1);if(t.elite)addMasteryProgress('hunter','eliteTargets',1);if(t.done>=t.amount){save.quests.combat=save.quests.combat||{warrior:0,ranger:0,mage:0,summoner:0,elites:0,bosses:0,hunterAssignments:0,eliteHunterAssignments:0};save.quests.combat.hunterAssignments=(Number(save.quests.combat.hunterAssignments)||0)+1;if(t.elite)save.quests.combat.eliteHunterAssignments=(Number(save.quests.combat.eliteHunterAssignments)||0)+1;addMasteryProgress('hunter','assignments',1);if(t.elite)addMasteryProgress('hunter','eliteAssignments',1);addPerkProgress('huntertask',1);let coins=Math.round(t.amount*10*(save.hunter.unlocks.cache?1.5:1)),reward=hunterRewardScale(t);t.xp=reward.xp;t.points=reward.points;addXP('Monster Hunter',reward.xp);var masteryHunterPoints=masteryPassive('hunter')?Math.ceil(reward.points*1.15):reward.points;save.hunter.points+=masteryHunterPoints;save.coins+=coins;var bonusItem=null;if(masteryPassive('hunter')&&Math.random()<.10){var masteryHunterPool=['Copper ore','Tin ore','Logs','Ironvale ore','Oakheart logs','Spirit Shard'];bonusItem=masteryHunterPool[Math.floor(Math.random()*masteryHunterPool.length)];save.bank[bonusItem]=(save.bank[bonusItem]||0)+1;save.drops.push('HUNTER MASTERY! Bonus Guild Reward: '+bonusItem)}save.drops.push('Hunter assignment complete: +'+t.xp+' XP, +'+masteryHunterPoints+' points, +'+coins+' coins');t.points=masteryHunterPoints;showHunterComplete(t,coins,bonusItem);save.hunter.task=null;persist()}else if(t.done%5===0)writeSave(false)}
function buyHunterUnlock(key){let u=hunterShop.find(x=>x.key===key);if(!u||save.hunter.unlocks[key])return;if(u.requires&&!save.hunter.unlocks[u.requires]){alert('You need Veteran Contracts first.');return}if(save.hunter.points<u.cost){alert('You need '+u.cost+' Hunter Points.');return}save.hunter.points-=u.cost;save.hunter.unlocks[key]=true;if(u.item){if(itemDB[u.item]&&itemDB[u.item].legacyShared){['warrior','ranger','mage','summoner'].forEach(function(cls){var rewardName=classGearName(u.item,cls);save.items[rewardName]=(save.items[rewardName]||0)+1});save.drops.push('Hunter Guild reward: class-specific '+u.item+' set')}else{save.items[u.item]=(save.items[u.item]||0)+1;save.drops.push('Hunter Guild reward: '+u.item)}}persist()}window.buyHunterUnlock=buyHunterUnlock;
