function ensureMasterySave(){
 if(!Array.isArray(masteryDefinitions))return;
 save.mastery=save.mastery&&typeof save.mastery==='object'?save.mastery:{skills:{},trial:{unlocked:false,completed:false},maxCape:false};
 save.mastery.skills=save.mastery.skills&&typeof save.mastery.skills==='object'?save.mastery.skills:{};
 masteryDefinitions.forEach(function(d){var m=save.mastery.skills[d.id];if(!m||typeof m!=='object')m=save.mastery.skills[d.id]={progress:{},mastered:false,claimed:false};m.progress=m.progress&&typeof m.progress==='object'?m.progress:{};m.mastered=!!m.mastered;m.claimed=!!m.claimed;d.objectives.forEach(function(o){m.progress[o[0]]=Math.max(0,Number(m.progress[o[0]])||0)})});
 save.mastery.trial=save.mastery.trial&&typeof save.mastery.trial==='object'?save.mastery.trial:{unlocked:false,completed:false};
 save.mastery.maxCape=!!save.mastery.maxCape;save.mastery.titles=Array.isArray(save.mastery.titles)?save.mastery.titles:[];save.mastery.activeTitle=save.mastery.activeTitle||'';
}
function masteryCanTrack(id){var d=masteryDefinitions.find(function(x){return x.id===id});return !!(d&&save.skills[d.skill]&&save.skills[d.skill].lvl>=99)}
let masterySaveTimer=null;function queueMasterySave(){if(masterySaveTimer)return;masterySaveTimer=setTimeout(function(){masterySaveTimer=null;writeSave(false);scheduleCloudSave()},750)}
function addMasteryProgress(id,key,amount){if(!masteryCanTrack(id))return;ensureMasterySave();var d=masteryDefinitions.find(function(x){return x.id===id}),o=d&&d.objectives.find(function(x){return x[0]===key});if(!o)return;var m=save.mastery.skills[id];m.progress[key]=Math.min(o[2],Math.max(0,(Number(m.progress[key])||0)+(Number(amount)||0)));queueMasterySave()}
function resetMasteryProgress(id,key){if(!masteryCanTrack(id))return;ensureMasterySave();if(save.mastery.skills[id]&&save.mastery.skills[id].progress)save.mastery.skills[id].progress[key]=0}
