function trackGatherMastery(type,g,qty){if(!g||!masteryCanTrack(g.skill==='Mining'?'mining':g.skill==='Woodcutting'?'woodcutting':g.skill==='Fishing'?'fishing':''))return;var id=g.skill==='Mining'?'mining':g.skill==='Woodcutting'?'woodcutting':'fishing';if(id==='mining'){addMasteryProgress(id,'totalOre',qty);if(['frostsilver','bogiron','moonstone'].includes(type))addMasteryProgress(id,'highTierOre',qty);if(type==='moonstone')addMasteryProgress(id,'moonstone',qty);if(qty>1)addMasteryProgress(id,'doubleOre',1)}else if(id==='woodcutting'){addMasteryProgress(id,'totalLogs',qty);if(['frostpine','rotwood','glowbark'].includes(type))addMasteryProgress(id,'highTierLogs',qty);if(type==='glowbark')addMasteryProgress(id,'glowbark',qty);if(qty>1)addMasteryProgress(id,'doubleLogs',1)}else{addMasteryProgress(id,'totalFish',qty);if(['frostsalmon','moonfin'].includes(type))addMasteryProgress(id,'highTierFish',qty);if(type==='moonfin')addMasteryProgress(id,'moonfin',qty);if(qty>1)addMasteryProgress(id,'doubleFish',1)}}
function trackCookingMastery(key,qty,burned){if(!masteryCanTrack('cooking'))return;if(burned){resetMasteryProgress('cooking','perfectStreak');return}addMasteryProgress('cooking','totalFood',qty);if(['frostsalmon','moonfin'].includes(key))addMasteryProgress('cooking','highTierFood',qty);if(key==='moonfin')addMasteryProgress('cooking','moonfin',qty);addMasteryProgress('cooking','perfectStreak',1)}
