function trackArtisanMastery(r,qty){if(!r)return;var id=r.skill==='Fletching'?'fletching':r.skill==='Crafting'?'crafting':null;if(!id||!masteryCanTrack(id))return;if(id==='fletching'){addMasteryProgress(id,'totalItems',qty);if(r.level>=30)addMasteryProgress(id,'highTierItems',qty);if(Object.prototype.hasOwnProperty.call(r.cost,'Glowbark logs'))addMasteryProgress(id,'glowbarkItems',qty);if(r.level>=50&&/bow|recurve|quiver/i.test(r.name))addMasteryProgress(id,'topTierRanged',qty)}else{addMasteryProgress(id,'totalItems',qty);if(r.level>=40)addMasteryProgress(id,'highTierItems',qty);if(r.outputBank==='Lunarweave Cloth'||/Lunarweave/i.test(r.name))addMasteryProgress(id,'lunarweave',qty);if(r.level>=40&&!r.outputBank&&itemDB[r.name])addMasteryProgress(id,'wearableGear',qty)}}
