function trackCombatKill(type,target){if(!target)return;save.quests.combat=save.quests.combat||{warrior:0,ranger:0,mage:0,summoner:0,elites:0,bosses:0,hunterAssignments:0,eliteHunterAssignments:0};if(['warrior','ranger','mage','summoner'].includes(type))save.quests.combat[type]=(Number(save.quests.combat[type])||0)+1;if(masteryEliteEnemy(target))save.quests.combat.elites=(Number(save.quests.combat.elites)||0)+1;if(masteryBossKinds.has(target.kind))save.quests.combat.bosses=(Number(save.quests.combat.bosses)||0)+1;if(target.lunaraRegion||['moonsprite','glimmerling','sporewalker','moonfang','lunarsentinel','starweaver','astralgolem','voidborn','moonweaver','dreamshade','dreamkeeper','dreameater'].includes(target.kind))addPerkProgress('lunarakill',1);var elite=masteryEliteEnemy(target),boss=masteryBossKinds.has(target.kind);if(type==='warrior'){addMasteryProgress('attack','warriorKills',1);if(elite)addMasteryProgress('attack','warriorElites',1);if(boss){addMasteryProgress('attack','warriorBossFinishes',1);addMasteryProgress('strength','warriorBosses',1)}}else if(type==='ranger'){addMasteryProgress('ranged','rangerKills',1);if(elite)addMasteryProgress('ranged','rangerElites',1);if(boss)addMasteryProgress('ranged','rangerBossFinishes',1)}else if(type==='mage'){addMasteryProgress('magic','mageKills',1);if(elite)addMasteryProgress('magic','mageElites',1);if(boss)addMasteryProgress('magic','mageBossFinishes',1)}else if(type==='summoner'){addMasteryProgress('summoning','summonerKills',1);if(elite)addMasteryProgress('summoning','summonerElites',1);addPerkProgress('summonkill',1)}if(elite){addPerkProgress('elitekill',1);target._masteryEliteCounted=true;save.drops.push('Elite defeated by '+type+' tower — Mastery kill counted!');if(save.drops.length>20)save.drops.shift()}}
function trackBattleCompletion(kind){save.quests.activities=save.quests.activities||{dungeons:0,flawlessDungeons:0,raids:0,flawlessRaids:0};if(kind==='dungeon'){save.quests.activities.dungeons=(Number(save.quests.activities.dungeons)||0)+1;if(lives>=20)save.quests.activities.flawlessDungeons=(Number(save.quests.activities.flawlessDungeons)||0)+1}else if(kind==='raid'){save.quests.activities.raids=(Number(save.quests.activities.raids)||0)+1;if(lives>=20)save.quests.activities.flawlessRaids=(Number(save.quests.activities.flawlessRaids)||0)+1}if(kind==='map'){addMasteryProgress('hitpoints','maps',1);if(lives>=20)addMasteryProgress('defence','flawlessMaps',1)}else if(kind==='boss'){addMasteryProgress('hitpoints','bosses',1);if(lives>=20)addMasteryProgress('defence','flawlessBosses',1)}else if(kind==='dungeon'){addMasteryProgress('hitpoints','dungeons',1);if(lives>=20)addMasteryProgress('defence','flawlessDungeons',1);if(towers.some(function(t){return t.type==='warrior'}))addMasteryProgress('attack','warriorDungeons',1)}else if(kind==='raid'){addMasteryProgress('hitpoints','raids',1);if(lives>=20)addMasteryProgress('defence','flawlessRaids',1)}}
function masteryComplete(id){var d=masteryDefinitions.find(function(x){return x.id===id}),m=save.mastery.skills[id];return !!(d&&m&&save.skills[d.skill]&&save.skills[d.skill].lvl>=99&&d.objectives.every(function(o){return (Number(m.progress[o[0]])||0)>=o[2]}))}function refreshMasteryCompletion(){ensureMasterySave();masteryDefinitions.forEach(function(d){var m=save.mastery.skills[d.id];if(!m.mastered&&masteryComplete(d.id))m.mastered=true})}function showMasteryCelebration(d){var m=document.getElementById('masteryCompleteModal');if(!m){m=document.createElement('div');m.id='masteryCompleteModal';m.className='modal';m.setAttribute('aria-hidden','true');m.innerHTML='<div class="modalCard masteryCompleteCard"><h2>👑 SKILL MASTERED 👑</h2><div id="masteryCompleteBody"></div><button onclick="closeMasteryComplete()">Continue</button></div>';document.body.appendChild(m)}var b=document.getElementById('masteryCompleteBody');if(b)b.innerHTML='<h3>'+d.icon+' '+(d.display||d.skill)+'</h3><p>You have completed every '+(d.display||d.skill)+' Mastery objective.</p><div class="masteryReward"><div class="masteryCapePreview claimPreview">'+(masteryArtwork[masteryCapeStats[d.id].name]?'<img src="'+masteryArtwork[masteryCapeStats[d.id].name]+'" alt="'+masteryCapeStats[d.id].name+' artwork">':'🎖️')+'<b>'+masteryCapeStats[d.id].name+'</b></div><br>🏷️ <b>'+d.title+'</b><br>⭐ '+d.passive+'</div>';m.classList.add('show');m.setAttribute('aria-hidden','false')}function closeMasteryComplete(){var m=document.getElementById('masteryCompleteModal');if(m){m.classList.remove('show');m.setAttribute('aria-hidden','true')}}window.closeMasteryComplete=closeMasteryComplete;function claimMastery(id){ensureMasterySave();var d=masteryDefinitions.find(function(x){return x.id===id});if(!d)return;var m=save.mastery.skills[id];if(!masteryComplete(id)){alert('Complete every Mastery objective first.');return}m.mastered=true;if(m.claimed)return;var cape=masteryCapeStats[id].name;m.claimed=true;save.items[cape]=(save.items[cape]||0)+1;if(!save.mastery.titles.includes(d.title))save.mastery.titles.push(d.title);save.mastery.activeTitle=d.title;save.collection[cape]=true;persist();showMasteryCelebration(d)}window.claimMastery=claimMastery;function maxCapeEquipped(){return ['warrior','ranger','mage','summoner'].some(function(c){return save.equipment&&save.equipment[c]&&save.equipment[c].cape==='Realmforge Max Cape'})}
function masterySurge(){return maxMasteryPassive()&&maxCapeEquipped()&&Math.random()<.05}
